#[derive(Debug)]
struct Node {
    name: String,
    total: u64,
    parent: Option<usize>,
    children: Vec<usize>, // indices in nodes vec, order preserved insertion
    child_map: HashMap<String, usize>, // for quick lookup during building
    x0: u64,
    x1: u64,
    depth: usize,
    insertion_index: usize,
}

impl Node {
    fn new(name: String, parent: Option<usize>, depth: usize, insertion_index: usize) -> Self {
        Node {
            name,
            total: 0,
            parent,
            children: Vec::new(),
            child_map: HashMap::new(),
            x0: 0,
            x1: 0,
            depth,
            insertion_index,
        }
    }
}

fn parse_folded(input: &str) -> (Vec<Node>, u64) {
    // Returns nodes vec with root at 0, and total
    let mut nodes: Vec<Node> = Vec::new();
    // root "all"
    nodes.push(Node::new("all".to_string(), None, 0, 0));
    nodes[0].total = 0;

    for line in input.lines() {
        let trimmed = line.trim();
        if trimmed.is_empty() {
            continue;
        }
        // split last space
        // Find last whitespace
        let pos = trimmed.rfind(|c: char| c.is_whitespace());
        if pos.is_none() {
            continue;
        }
        let pos = pos.unwrap();
        let stack_part = trimmed[..pos].trim();
        let count_part = trimmed[pos..].trim();
        if stack_part.is_empty() || count_part.is_empty() {
            continue;
        }
        let count: u64 = match count_part.parse() {
            Ok(v) => v,
            Err(_) => continue,
        };
        if stack_part.is_empty() {
            continue;
        }
        let frames: Vec<&str> = stack_part.split(';').collect();
        if frames.is_empty() {
            continue;
        }
        // Clean frames: trim, but keep as is if not empty?
        let mut current_idx = 0;
        nodes[0].total += count;
        for frame in frames {
            let f = frame.trim();
            if f.is_empty() {
                continue;
            }
            // Find child
            let child_idx_opt = {
                let parent = &nodes[current_idx];
                parent.child_map.get(f).cloned()
            };
            let child_idx = if let Some(idx) = child_idx_opt {
                idx
            } else {
                let new_idx = nodes.len();
                let depth = nodes[current_idx].depth + 1;
                let insertion = nodes[current_idx].children.len();
                let mut new_node = Node::new(f.to_string(), Some(current_idx), depth, insertion);
                // total will be added after
                nodes.push(new_node);
                // Update parent
                nodes[current_idx].children.push(new_idx);
                nodes[current_idx].child_map.insert(f.to_string(), new_idx);
                new_idx
            };
            nodes[child_idx].total += count;
            current_idx = child_idx;
        }
    }

    (nodes, nodes[0].total)
}

fn assign_positions(nodes: &mut Vec<Node>, sorted: bool) {
    // BFS by depth
    // root x0=0 x1=total
    if nodes.is_empty() { return; }
    let total = nodes[0].total;
    nodes[0].x0 = 0;
    nodes[0].x1 = total;

    // We need to process nodes in order of depth increasing, so that parent x0 already assigned
    // Collect indices sorted by depth
    let mut order: Vec<usize> = (0..nodes.len()).collect();
    order.sort_by_key(|&i| nodes[i].depth);
    for idx in order {
        let parent_x0 = nodes[idx].x0;
        // let parent_x1 = nodes[idx].x1;
        // Determine children order
        let mut children = nodes[idx].children.clone();
        if sorted {
            // sort by total descending, and for tie, maybe insertion order? But observed tie picks last as max, so for visual order descending, stable?
            // For total equal, keep insertion order? But we need descending, so larger first.
            // To have tie break where last inserted is considered larger? However for layout, if equal totals, order could be insertion order or sorted stable?
            // Original sorted likely sorts descending total, and for equal, maybe insertion order preserved? Let's sort by total descending, then by insertion_index ascending for stability.
            // We'll sort by total descending
            children.sort_by(|&a, &b| {
                let ta = nodes[a].total;
                let tb = nodes[b].total;
                tb.cmp(&ta).then_with(|| nodes[a].insertion_index.cmp(&nodes[b].insertion_index))
            });
        }
        // else keep insertion order (already)
        // Assign positions
        let mut offset: u64 = 0;
        for &c_idx in &children {
            nodes[c_idx].x0 = parent_x0 + offset;
            nodes[c_idx].x1 = nodes[c_idx].x0 + nodes[c_idx].total;
            offset += nodes[c_idx].total;
        }
        // Note: exclusive gap not represented
    }
}

fn build_depth_index(nodes: &Vec<Node>) -> Vec<Vec<usize>> {
    let max_depth = nodes.iter().map(|n| n.depth).max().unwrap_or(0);
    let mut depth_index: Vec<Vec<usize>> = vec![Vec::new(); max_depth+1];
    for (i,n) in nodes.iter().enumerate() {
        depth_index[n.depth].push(i);
    }
    // For each depth, sort by x0
    for d in 0..=max_depth {
        depth_index[d].sort_by_key(|&i| nodes[i].x0);
    }
    depth_index
}

