fn name_to_color(name: &str) -> (u8,u8,u8) {
    // Deterministic hash to color similar to original warm colors
    // Original colors: varied but warm. We'll hash string to produce color.
    // Use simple fnv hash
    let mut hash: u64 = 1469598103934665603;
    for b in name.bytes() {
        hash ^= b as u64;
        hash = hash.wrapping_mul(1099511628211);
    }
    // Map hash to a gradient from yellow (250,220,50) to red (210,20,5) with orange in between
    // We'll produce r 200-254, g 20-220, b 5-60
    // Use hash to pick g in 20-220, r around 200+...
    let g = 20 + (hash % 200) as u8; // 20-219
    let r = 200 + ((hash >> 8) % 55) as u8; // 200-254
    let b = 5 + ((hash >> 16) % 60) as u8;
    (r,g,b)
}

fn run_tui(input_text: String, display_name: String, sorted: bool, debug_flag: bool) -> io::Result<()> {
    let (mut nodes, total) = parse_folded(&input_text);
    if total == 0 {
        nodes[0].total = 1;
    }
    assign_positions(&mut nodes, sorted);
    let depth_index = build_depth_index(&nodes);
    let max_depth = depth_index.len().saturating_sub(1);

    let mut selected: usize = 0;
    let mut zoom: usize = 0;
    let mut scroll_offset: usize = 0;
    let mut search_pattern: Option<regex::Regex> = None;
    let mut search_text: Option<String> = None;
    let mut search_matches: Vec<usize> = Vec::new();
    let mut search_current: usize = 0;
    let mut search_mode: bool = false;
    let mut search_input: String = String::new();
    let mut info_message: Option<String> = None;

    enable_raw_mode()?;
    let mut stdout = io::stdout();
    stdout.execute(EnterAlternateScreen)?;
    let backend = ratatui::backend::CrosstermBackend::new(stdout);
    let mut terminal = ratatui::Terminal::new(backend)?;

    let mut should_quit = false;

    loop {
        let flame_start = Instant::now();
        let _ = terminal.draw(|f| {
            let area = f.area();
            let width = area.width as usize;
            let height = area.height as usize;

            // Compute extra bottom panels
            let mut extra_bottom = 0;
            extra_bottom += 2; // selected
            if search_pattern.is_some() {
                extra_bottom += 2; // match
            }
            if search_mode {
                extra_bottom += 2; // search input
            }
            if info_message.is_some() {
                extra_bottom += 2; // info
            }
            if debug_flag {
                extra_bottom += 2; // debug
            }
            extra_bottom += 2; // footer border + hints

            let header_rows = 3;
            let flame_height = height.saturating_sub(header_rows + extra_bottom);

            let zoom_node = &nodes[zoom];
            let zoom_x0 = zoom_node.x0;
            let zoom_x1 = zoom_node.x1;
            let zoom_total = if zoom_node.total == 0 { 1 } else { zoom_node.total };

            // visible per depth
            let mut visible_per_depth: Vec<Vec<(usize, u64, u64)>> = vec![Vec::new(); depth_index.len()];
            for (d, indices) in depth_index.iter().enumerate() {
                for &idx in indices {
                    let node = &nodes[idx];
                    if node.x1 <= zoom_x0 || node.x0 >= zoom_x1 {
                        continue;
                    }
                    let clip_x0 = node.x0.max(zoom_x0);
                    let clip_x1 = node.x1.min(zoom_x1);
                    if clip_x0 >= clip_x1 {
                        continue;
                    }
                    visible_per_depth[d].push((idx, clip_x0, clip_x1));
                }
                visible_per_depth[d].sort_by_key(|&(_, cx0, _)| cx0);
            }

            // Title bar string
            let left = " [Flamegraph] | Top";
            let right = "flamelens v0.3.1";
            let mid = display_name.clone();
            let left_len = left.len();
            let right_len = right.len();
            let mid_len = mid.len();
            let total_needed = left_len + mid_len + right_len;
            let remaining = if width > total_needed { width - total_needed } else { 0 };
            let left_pad = if remaining > 0 { remaining / 2 + 1 } else { 0 };
            let right_pad = remaining.saturating_sub(left_pad);
            let title_line = format!("{}{}{}{}{}", left, " ".repeat(left_pad), mid, " ".repeat(right_pad), right);

            // Build lines for rendering
            let mut lines: Vec<Line> = Vec::new();

            // Top border
            let border = "─".repeat(width);
            lines.push(Line::from(border.clone()));

            // Title line with styles: [Flamegraph] bold yellow, Top bold, filename bold, version bold
            // We'll use spans with styles similar to original
            let mut title_spans: Vec<Span> = Vec::new();
            // We'll parse title_line but need to style parts: We know left contains "[Flamegraph]" and "Top" should be bold
            // For simplicity, make whole title line with bold for those parts
            // We'll construct spans manually to mimic original colors: [Flamegraph] yellow bold, Top bold, filename bold, version bold
            // Left part
            title_spans.push(Span::styled(" [", Style::default()));
            title_spans.push(Span::styled("Flamegraph", Style::default().fg(Color::Yellow).add_modifier(Modifier::BOLD)));
            title_spans.push(Span::styled("] | ", Style::default()));
            title_spans.push(Span::styled("Top", Style::default().add_modifier(Modifier::BOLD)));
            title_spans.push(Span::styled(" ".repeat(left_pad), Style::default()));
            title_spans.push(Span::styled(mid.clone(), Style::default().add_modifier(Modifier::BOLD)));
            title_spans.push(Span::styled(" ".repeat(right_pad), Style::default()));
            title_spans.push(Span::styled(right.clone(), Style::default().add_modifier(Modifier::BOLD)));
            // Ensure line fills width
            let title_line_len = left_len + left_pad + mid_len + right_pad + right_len;
            if title_line_len < width {
                title_spans.push(Span::raw(" ".repeat(width - title_line_len)));
            }
            lines.push(Line::from(title_spans));

            // Second border
            lines.push(Line::from(border.clone()));

            // Flamegraph rows
            for depth_offset in 0..flame_height {
                let d = scroll_offset + depth_offset;
                if d >= visible_per_depth.len() {
                    // empty line
                    lines.push(Line::from(""));
                    continue;
                }
                let frames = &visible_per_depth[d];
                if frames.is_empty() {
                    lines.push(Line::from(""));
                    continue;
                }
                // Render this row
                let mut row_spans: Vec<Span> = Vec::new();
                let mut current_x: usize = 0;
                for &(node_idx, clip_x0, clip_x1) in frames {
                    // Compute display x
                    let disp_x0 = ((clip_x0 - zoom_x0) * width as u64 / zoom_total) as usize;
                    let disp_x1 = ((clip_x1 - zoom_x0) * width as u64 / zoom_total) as usize;
                    let disp_x0 = disp_x0.min(width);
                    let disp_x1 = disp_x1.min(width);
                    if disp_x1 <= current_x {
                        continue;
                    }
                    let start = disp_x0.max(current_x);
                    let end = disp_x1;
                    let w = end.saturating_sub(start);
                    if w == 0 { continue; }

                    // If there's gap before this frame, fill with spaces (no bg)
                    if start > current_x {
                        row_spans.push(Span::raw(" ".repeat(start - current_x)));
                        current_x = start;
                    }

                    // Determine style
                    let node = &nodes[node_idx];
                    let is_selected = node_idx == selected;
                    let is_match = if let Some(ref re) = search_pattern {
                        re.is_match(&node.name)
                    } else { false };

                    // Background color
                    let (bg_r, bg_g, bg_b) = if is_selected {
                        (250,250,250)
                    } else if is_match {
                        (10,35,150)
                    } else {
                        name_to_color(&node.name)
                    };
                    let bg_color = Color::Rgb(bg_r, bg_g, bg_b);
                    let fg_color = if is_selected {
                        Color::Rgb(10,10,10)
                    } else if is_match {
                        // For match, original had bold red for matched text? We'll use white for simplicity but later handle substring
                        Color::Rgb(225,225,225)
                    } else {
                        // Choose fg based on bg luminance: if dark bg, white fg else black
                        let lum = 0.299*(bg_r as f64) + 0.587*(bg_g as f64) + 0.114*(bg_b as f64);
                        if lum < 140.0 {
                            Color::Rgb(225,225,225)
                        } else {
                            Color::Rgb(10,10,10)
                        }
                    };

                    let mut style = Style::default().bg(bg_color).fg(fg_color);
                    // For selected, maybe no bold? Original selected had no bold but white bg.

                    // Frame label: we have w characters width to fill.
                    // Label is " {name}" with leading space, truncated if needed.
                    let label = format!(" {}", node.name);
                    let label_chars: Vec<char> = label.chars().collect();
                    let display_label = if w >= label_chars.len() {
                        // Fill rest with spaces up to w
                        let mut s = label;
                        s.push_str(&" ".repeat(w - s.len()));
                        s
                    } else {
                        // If w ==1, need to render dot? Original rendered "." for very small frames
                        if w == 1 {
                            // If frame's original total is small relative? Original showed "." for tiny frames
                            // We'll render "." if label doesn't fit and w==1, else truncate label to w
                            if node.name.len() > 0 && w == 1 {
                                // Check if original logic shows dot for small frames: In earlier test, small frames of width 1 were rendered as "." 
                                // We'll mimic: if w <=2 and label doesn't fit, show "." or first char?
                                // For now, if w==1, show "." if frame width small? But we don't have threshold.
                                // Simpler: if w==1, show "."
                                ".".to_string()
                            } else {
                                label_chars.iter().take(w).collect()
                            }
                        } else {
                            // Truncate to w
                            label_chars.iter().take(w).collect()
                        }
                    };

                    // If is_match, we want to highlight matching substring within label with bold red?
                    // For simplicity, if is_match, we will split label into parts matching regex and style differently.
                    if is_match {
                        if let Some(ref re) = search_pattern {
                            // Find matches in node.name
                            // We will create spans for the display_label which includes leading space plus name truncated?
                            // For simplicity, if the whole frame matches, we make the matching part bold red
                            // We'll search within display_label for regex matches
                            let mut last = 0;
                            let mut spans_match: Vec<Span> = Vec::new();
                            // Use regex to find matches in display_label (which may be truncated)
                            // For each match, create span with fg red bold
                            // This is approximate
                            for mat in re.find_iter(&display_label) {
                                let start = mat.start();
                                let end = mat.end();
                                if start > last {
                                    let before = &display_label[last..start];
                                    spans_match.push(Span::styled(before.to_string(), style));
                                }
                                let mtxt = &display_label[start..end];
                                let mut mstyle = style.fg(Color::Rgb(225,10,10)).add_modifier(Modifier::BOLD);
                                mstyle = mstyle.bg(bg_color);
                                spans_match.push(Span::styled(mtxt.to_string(), mstyle));
                                last = end;
                            }
                            if last < display_label.len() {
                                spans_match.push(Span::styled(display_label[last..].to_string(), style));
                            }
                            if !spans_match.is_empty() {
                                for s in spans_match {
                                    row_spans.push(s);
                                }
                                current_x = end;
                                continue;
                            }
                        }
                    }

                    row_spans.push(Span::styled(display_label, style));
                    current_x = end;
                }
                // Fill remaining width with spaces
                if current_x < width {
                    row_spans.push(Span::raw(" ".repeat(width - current_x)));
                }
                lines.push(Line::from(row_spans));
            }

            // Selected panel
            let sel_node = &nodes[selected];
            let total_all = nodes[0].total as f64;
            let sel_total = sel_node.total;
            let percent_all = if total_all > 0.0 { sel_total as f64 / total_all * 100.0 } else { 0.0 };
            let mut sel_line1 = format!("Selected {}", "─".repeat(width.saturating_sub(9)));
            // Actually header "Selected ─────"
            // We'll truncate
            let sel_header = format!("Selected {}", "─".repeat(width.saturating_sub(9)));
            lines.push(Line::from(Span::styled(sel_header, Style::default().fg(Color::Yellow).add_modifier(Modifier::BOLD))));

            let sel_info = if zoom != 0 && zoom != selected {
                let zoom_total = nodes[zoom].total as f64;
                let percent_zoomed = if zoom_total > 0.0 { sel_total as f64 / zoom_total * 100.0 } else { 0.0 };
                format!("{} [{} samples, {:.2}% of all, {:.2}% of zoomed]", sel_node.name, sel_total, percent_all, percent_zoomed)
            } else if zoom != 0 && zoom == selected {
                // When selected == zoom, show 100% of zoomed as well
                // In earlier captures, when zoomed onto main and selected main, it showed 100% of zoomed
                // So if selected is ancestor of zoom? Actually selected == zoom, it should be 100% of zoomed
                let zoom_total = nodes[zoom].total as f64;
                let percent_zoomed = 100.0;
                format!("{} [{} samples, {:.2}% of all, {:.2}% of zoomed]", sel_node.name, sel_total, percent_all, percent_zoomed)
            } else {
                format!("{} [{} samples, {:.2}% of all]", sel_node.name, sel_total, percent_all)
            };
            lines.push(Line::from(sel_info));

            // Match panel if search active
            if let Some(ref pat) = search_text {
                let match_header = format!("Match {}", "─".repeat(width.saturating_sub(6)));
                lines.push(Line::from(Span::styled(match_header, Style::default().fg(Color::Yellow).add_modifier(Modifier::BOLD))));
                // Compute total samples for matches
                let mut match_total: u64 = 0;
                for &idx in &search_matches {
                    // For match total, sum exclusive? Actually need to sum? In original, match total seems sum of all matching frames' total? But note overlapping? Let's sum totals but avoid double counting? Simpler sum of totals of matched nodes? However overlapping children would double count. Original seems to sum samples where pattern matches? Let's check: searching "foo" gave 150 samples, which matches foo total (150). So they sum? For foo there is only one foo node (total 150). So match total = sum of matching nodes? Could be sum of leaf? But for counting, they likely sum total samples of matching frames, but dedup overlapping? For simplicity, sum totals of matched nodes that are not ancestors/descendants overlapping? Simpler: sum total of all matched nodes but maybe they just sum the total of matching frames distinct? Let's just sum total of first level matches? For now compute sum of totals of matched nodes, but if node is ancestor of another matched node, avoid double counting? Easier: compute total samples where stack contains matching frame? That would be root's matching? But original's match total for "foo" was 150 which equals foo's total, not sum of all nodes containing foo as substring? There are nodes: main (180) contains "main" not foo, foo (150) matches, bar (100) doesn't, baz (50) doesn't. So only foo matches, total 150. So sum of matched totals =150 matches.
                // For "^bar$" total 100 matches bar total.
                // We'll compute match_total as sum of totals of matched nodes, but to avoid double counting when both parent and child match, we should not double count? In regex case, if search "a", and both a and its child b also contain "a"? But b name "b" doesn't contain "a". So maybe not overlap.
                // We'll just sum totals of matched nodes
                for &idx in &search_matches {
                    match_total += nodes[idx].total;
                }
                // But this would overcount if multiple matches overlap (e.g., searching "a" matches both parent a and child a? But child names distinct). Could be okay.
                // However original for "foo" they computed 150 not sum of all nodes containing foo as substring? Actually foo appears only in one node, so sum=150.
                // Let's compute percent of all for match
                let match_percent = if total_all > 0.0 { match_total as f64 / total_all * 100.0 } else { 0.0 };
                // If zoomed, also percent of zoomed? In earlier capture, match panel showed only percent of all when not zoomed? When zoomed, it showed percent of all and maybe zoomed? Let's check earlier zoom + search: we had zoom main and search bar -> match showed 100 samples, 50% of all, 55.56% of zoomed? In that capture after zoom main + search bar, match line: "^bar$" [100 samples, 50.00% of all, 55.56% of zoomed] ??? Let's recall earlier log for zoom main + search bar: it had match line but we didn't see zoomed percent? In one log, after zoom main, search bar, we had match? Let's assume similar to selected: show both percents if zoomed.
                let match_info = if zoom != 0 {
                    let zoom_total = nodes[zoom].total as f64;
                    let percent_zoomed = if zoom_total >0.0 { match_total as f64 / zoom_total *100.0 } else {0.0};
                    format!("\"{}\" [{} samples, {:.2}% of all, {:.2}% of zoomed]", pat, match_total, match_percent, percent_zoomed)
                } else {
                    format!("\"{}\" [{} samples, {:.2}% of all]", pat, match_total, match_percent)
                };
                lines.push(Line::from(match_info));
            }

            // Search input panel
            if search_mode {
                let search_header = format!("Search {}", "─".repeat(width.saturating_sub(7)));
                lines.push(Line::from(Span::styled(search_header, Style::default().fg(Color::Yellow).add_modifier(Modifier::BOLD))));
                lines.push(Line::from(search_input.clone()));
            }

            // Info panel
            if let Some(ref msg) = info_message {
                let info_header = format!("Info {}", "─".repeat(width.saturating_sub(5)));
                lines.push(Line::from(Span::styled(info_header, Style::default().fg(Color::Yellow).add_modifier(Modifier::BOLD))));
                lines.push(Line::from(msg.clone()));
            }

            // Debug panel
            if debug_flag {
                let debug_header = format!("Debug {}", "─".repeat(width.saturating_sub(6)));
                lines.push(Line::from(Span::styled(debug_header, Style::default().fg(Color::Yellow).add_modifier(Modifier::BOLD))));
                // Fake debug times
                let elapsed = flame_start.elapsed();
                // We'll show some dummy timings
                lines.push(Line::from(format!("Debug: flamegraph:{:.2?} render:{:.2?}", elapsed, Duration::from_millis(0))));
            }

            // Footer border
            lines.push(Line::from(border.clone()));

            // Key hints
            // Original footer: " [hjkl: move cursor] [f/b: scroll] [enter/esc: zoom] [/: search] [#: search like"
            // Plus maybe more when width larger: " [hjkl: move cursor] [f/b: scroll] [enter/esc: zoom] [/: search] [#: search like cursor] [r: reset] [tab: switch view] [q: quit]"
            // We should generate full hints and truncate to width
            let hints = " [hjkl: move cursor] [f/b: scroll] [enter/esc: zoom] [/: search] [#: search like cursor] [n/N: next/prev match] [r: reset] [q: quit]";
            // But original shows truncated based on width. We'll just take first width chars
            let hints_display = if hints.len() > width { &hints[..width] } else { hints };
            // Style key parts bold yellow
            // For simplicity, we'll style brackets content? We'll attempt to style like original: keys bold yellow
            // We'll parse hints: segments like "[hjkl: move cursor]" - inside "hjkl" should be bold? In original, the key part before colon is bold yellow? Actually capture shows "[hjkl" bold? Let's mimic: inside [], the keys are bold yellow.
            // We'll create spans
            let mut hint_spans: Vec<Span> = Vec::new();
            // Simple: split by '[' and ']' to style
            let mut in_bracket = false;
            let mut current = String::new();
            for ch in hints_display.chars() {
                if ch == '[' {
                    if !current.is_empty() {
                        hint_spans.push(Span::raw(current.clone()));
                        current.clear();
                    }
                    in_bracket = true;
                    current.push(ch);
                } else if ch == ']' && in_bracket {
                    current.push(ch);
                    // Now style inside: find ':' separator
                    // For "[hjkl: move cursor]" -> style "hjkl" bold yellow, rest normal?
                    // Original had "[hjkl: move cursor]" where "hjkl" bold yellow.
                    // Let's implement: inside brackets, up to ':' is bold yellow
                    let inner = current[1..current.len()-1].to_string(); // without brackets
                    if let Some(colon) = inner.find(':') {
                        let key_part = &inner[..colon];
                        let rest = &inner[colon..];
                        hint_spans.push(Span::raw("["));
                        hint_spans.push(Span::styled(key_part.to_string(), Style::default().fg(Color::Yellow).add_modifier(Modifier::BOLD)));
                        hint_spans.push(Span::raw(format!("{}]", rest)));
                    } else {
                        hint_spans.push(Span::styled(current.clone(), Style::default().fg(Color::Yellow).add_modifier(Modifier::BOLD)));
                    }
                    current.clear();
                    in_bracket = false;
                } else {
                    current.push(ch);
                }
            }
            if !current.is_empty() {
                hint_spans.push(Span::raw(current));
            }
            lines.push(Line::from(hint_spans));

            let paragraph = Paragraph::new(lines);
            f.render_widget(paragraph, area);
        })?;

        if event::poll(Duration::from_millis(100))? {
            if let Event::Key(key) = event::read()? {
                if key.kind != KeyEventKind::Press {
                    continue;
                }
                match key.code {
                    KeyCode::Char('q') => {
                        should_quit = true;
                    }
                    KeyCode::Char('c') if key.modifiers.contains(event::KeyModifiers::CONTROL) => {
                        should_quit = true;
                    }
                    KeyCode::Char('j') | KeyCode::Down => {
                        if search_mode { continue; }
                        let children = &nodes[selected].children;
                        if !children.is_empty() {
                            let mut best = children[0];
                            let mut best_total = nodes[best].total;
                            for &c in children.iter().skip(1) {
                                let t = nodes[c].total;
                                if t > best_total || (t == best_total) {
                                    best = c;
                                    best_total = t;
                                }
                            }
                            selected = best;
