            let zoom_total = if zoom_node.total == 0 { 1 } else { zoom_node.total };

            let mut visible_per_depth: Vec<Vec<(usize, u64, u64)>> = vec![Vec::new(); depth_index.len()];
            for (d, indices) in depth_index.iter().enumerate() {
                for &idx in indices {
                    let node = &nodes[idx];
                    if node.x1 <= zoom_x0 || node.x0 >= zoom_x1 { continue; }
                    let clip_x0 = node.x0.max(zoom_x0);
                    let clip_x1 = node.x1.min(zoom_x1);
                    if clip_x0 >= clip_x1 { continue; }
                    visible_per_depth[d].push((idx, clip_x0, clip_x1));
