                        extra_bottom+=2;
                        let flame_h = height.saturating_sub(3+extra_bottom);
                        scroll_offset = scroll_offset.saturating_add(flame_h);
                        let max_scroll = max_depth.saturating_sub(flame_h.saturating_sub(1));
