#[derive(Debug)]
struct Node {
    name: String,
    total: u64,
    parent: Option<usize>,
    children: Vec<usize>,
    child_map: HashMap<String, usize>,
    x0: u64,
    x1: u64,
    depth: usize,
    insertion_index: usize,
}

impl Node {
    fn new(name: String, parent: Option<usize>, depth: usize, insertion_index: usize) -> Self {
        Node {
            name,
            total: 0,
            parent,
            children: Vec::new(),
            child_map: HashMap::new(),
            x0: 0,
            x1: 0,
            depth,
            insertion_index,
        }
    }
}

fn parse_folded(input: &str) -> (Vec<Node>, u64) {
    let mut nodes: Vec<Node> = Vec::new();
    nodes.push(Node::new("all".to_string(), None, 0, 0));
    nodes[0].total = 0;
    for line in input.lines() {
        let trimmed = line.trim();
        if trimmed.is_empty() { continue; }
        let pos = trimmed.rfind(|c: char| c.is_whitespace());
        if pos.is_none() { continue; }
        let pos = pos.unwrap();
        let stack_part = trimmed[..pos].trim();
        let count_part = trimmed[pos..].trim();
        if stack_part.is_empty() || count_part.is_empty() { continue; }
        let count: u64 = match count_part.parse() { Ok(v) => v, Err(_) => continue, };
        let frames: Vec<&str> = stack_part.split(';').collect();
        if frames.is_empty() { continue; }
        let mut current_idx = 0;
        nodes[0].total += count;
        for frame in frames {
            let f = frame.trim();
            if f.is_empty() { continue; }
            let child_idx_opt = {
                let parent = &nodes[current_idx];
                parent.child_map.get(f).cloned()
            };
            let child_idx = if let Some(idx) = child_idx_opt {
                idx
            } else {
                let new_idx = nodes.len();
                let depth = nodes[current_idx].depth + 1;
                let insertion = nodes[current_idx].children.len();
                let new_node = Node::new(f.to_string(), Some(current_idx), depth, insertion);
                nodes.push(new_node);
                nodes[current_idx].children.push(new_idx);
                nodes[current_idx].child_map.insert(f.to_string(), new_idx);
                new_idx
            };
            nodes[child_idx].total += count;
            current_idx = child_idx;
        }
    }
    let tot = nodes[0].total;
    (nodes, tot)
}

fn assign_positions(nodes: &mut Vec<Node>, sorted: bool) {
    if nodes.is_empty() { return; }
    let total = nodes[0].total;
    nodes[0].x0 = 0;
    nodes[0].x1 = total;
    let mut order: Vec<usize> = (0..nodes.len()).collect();
    order.sort_by_key(|&i| nodes[i].depth);
    for idx in order {
        let parent_x0 = nodes[idx].x0;
        let mut children = nodes[idx].children.clone();
        if sorted {
            children.sort_by(|&a, &b| {
                let ta = nodes[a].total;
                let tb = nodes[b].total;
                tb.cmp(&ta).then_with(|| nodes[a].insertion_index.cmp(&nodes[b].insertion_index))
            });
        }
        let mut offset: u64 = 0;
        for &c_idx in &children {
            nodes[c_idx].x0 = parent_x0 + offset;
            nodes[c_idx].x1 = nodes[c_idx].x0 + nodes[c_idx].total;
            offset += nodes[c_idx].total;
        }
    }
}

fn build_depth_index(nodes: &Vec<Node>) -> Vec<Vec<usize>> {
    let max_depth = nodes.iter().map(|n| n.depth).max().unwrap_or(0);
    let mut depth_index: Vec<Vec<usize>> = vec![Vec::new(); max_depth+1];
    for (i,n) in nodes.iter().enumerate() {
        depth_index[n.depth].push(i);
    }
    for d in 0..=max_depth {
        depth_index[d].sort_by_key(|&i| nodes[i].x0);
    }
    depth_index
}

use crossterm::{
    event::{self, Event, KeyCode, KeyEventKind},
    terminal::{disable_raw_mode, enable_raw_mode, EnterAlternateScreen, LeaveAlternateScreen},
    ExecutableCommand,
};
use ratatui::{
    prelude::*,
    widgets::Paragraph,
    text::{Line, Span},
};
use std::time::{Instant, Duration};

fn name_to_color(name: &str) -> (u8,u8,u8) {
    let mut hash: u64 = 1469598103934665603;
    for b in name.bytes() {
        hash ^= b as u64;
        hash = hash.wrapping_mul(1099511628211);
    }
    let g = 20 + (hash % 200) as u8;
    let r = 200 + ((hash >> 8) % 55) as u8;
    let b = 5 + ((hash >> 16) % 60) as u8;
    (r,g,b)
}

fn run_tui(input_text: String, display_name: String, sorted: bool, debug_flag: bool) -> io::Result<()> {
    let (mut nodes, total) = parse_folded(&input_text);
    if total == 0 {
        nodes[0].total = 1;
    }
    assign_positions(&mut nodes, sorted);
    let depth_index = build_depth_index(&nodes);
    let max_depth = depth_index.len().saturating_sub(1);

    let mut selected: usize = 0;
    let mut zoom: usize = 0;
    let mut scroll_offset: usize = 0;
    let mut search_pattern: Option<regex::Regex> = None;
    let mut search_text: Option<String> = None;
    let mut search_matches: Vec<usize> = Vec::new();
    let mut search_current: usize = 0;
    let mut search_mode: bool = false;
    let mut search_input: String = String::new();
    let mut info_message: Option<String> = None;

    enable_raw_mode()?;
    let mut stdout = io::stdout();
    stdout.execute(EnterAlternateScreen)?;
    let backend = ratatui::backend::CrosstermBackend::new(stdout);
    let mut terminal = ratatui::Terminal::new(backend)?;

    let mut should_quit = false;

    loop {
        let frame_start = Instant::now();
        terminal.draw(|f| {
            let area = f.area();
            let width = area.width as usize;
            let height = area.height as usize;

            let mut extra_bottom = 0;
            extra_bottom += 2;
            if search_pattern.is_some() { extra_bottom += 2; }
            if search_mode { extra_bottom += 2; }
            if info_message.is_some() { extra_bottom += 2; }
            if debug_flag { extra_bottom += 2; }
            extra_bottom += 2;

            let header_rows = 3;
            let flame_height = height.saturating_sub(header_rows + extra_bottom);

            let zoom_node = &nodes[zoom];
            let zoom_x0 = zoom_node.x0;
            let zoom_x1 = zoom_node.x1;
            let zoom_total = if zoom_node.total == 0 { 1 } else { zoom_node.total };

            let mut visible_per_depth: Vec<Vec<(usize, u64, u64)>> = vec![Vec::new(); depth_index.len()];
            for (d, indices) in depth_index.iter().enumerate() {
                for &idx in indices {
                    let node = &nodes[idx];
                    if node.x1 <= zoom_x0 || node.x0 >= zoom_x1 { continue; }
                    let clip_x0 = node.x0.max(zoom_x0);
                    let clip_x1 = node.x1.min(zoom_x1);
                    if clip_x0 >= clip_x1 { continue; }
                    visible_per_depth[d].push((idx, clip_x0, clip_x1));
                }
                visible_per_depth[d].sort_by_key(|&(_, cx0, _)| cx0);
            }

            let left = " [Flamegraph] | Top";
            let right = "flamelens v0.3.1";
            let mid = display_name.clone();
            let left_len = left.len();
            let right_len = right.len();
            let mid_len = mid.len();
            let total_needed = left_len + mid_len + right_len;
            let remaining = if width > total_needed { width - total_needed } else { 0 };
            let left_pad = if remaining > 0 { remaining / 2 + 1 } else { 0 };
            let right_pad = remaining.saturating_sub(left_pad);

            let mut lines: Vec<Line> = Vec::new();
            let border = "─".repeat(width);
            lines.push(Line::from(border.clone()));

            let mut title_spans: Vec<Span> = Vec::new();
            title_spans.push(Span::styled(" [", Style::default()));
            title_spans.push(Span::styled("Flamegraph", Style::default().fg(Color::Yellow).add_modifier(Modifier::BOLD)));
            title_spans.push(Span::styled("] | ", Style::default()));
            title_spans.push(Span::styled("Top", Style::default().add_modifier(Modifier::BOLD)));
            title_spans.push(Span::styled(" ".repeat(left_pad), Style::default()));
            title_spans.push(Span::styled(mid.clone(), Style::default().add_modifier(Modifier::BOLD)));
            title_spans.push(Span::styled(" ".repeat(right_pad), Style::default()));
            title_spans.push(Span::styled(right.clone(), Style::default().add_modifier(Modifier::BOLD)));
            let title_line_len = left_len + left_pad + mid_len + right_pad + right_len;
            if title_line_len < width {
                title_spans.push(Span::raw(" ".repeat(width - title_line_len)));
            }
            lines.push(Line::from(title_spans));
            lines.push(Line::from(border.clone()));

            for depth_offset in 0..flame_height {
                let d = scroll_offset + depth_offset;
                if d >= visible_per_depth.len() {
                    lines.push(Line::from(""));
                    continue;
                }
                let frames = &visible_per_depth[d];
                if frames.is_empty() {
                    lines.push(Line::from(""));
                    continue;
                }
                let mut row_spans: Vec<Span> = Vec::new();
                let mut current_x: usize = 0;
                for &(node_idx, clip_x0, clip_x1) in frames {
                    let disp_x0 = ((clip_x0 - zoom_x0) * width as u64 / zoom_total) as usize;
                    let disp_x1 = ((clip_x1 - zoom_x0) * width as u64 / zoom_total) as usize;
                    let disp_x0 = disp_x0.min(width);
                    let disp_x1 = disp_x1.min(width);
                    if disp_x1 <= current_x { continue; }
                    let start = disp_x0.max(current_x);
                    let end = disp_x1;
                    let w = end.saturating_sub(start);
                    if w == 0 { continue; }
                    if start > current_x {
                        row_spans.push(Span::raw(" ".repeat(start - current_x)));
                        current_x = start;
                    }
                    let node = &nodes[node_idx];
                    let is_selected = node_idx == selected;
                    let is_match = if let Some(ref re) = search_pattern { re.is_match(&node.name) } else { false };
                    let (bg_r, bg_g, bg_b) = if is_selected {
                        (250,250,250)
                    } else if is_match {
                        (10,35,150)
                    } else {
                        name_to_color(&node.name)
                    };
                    let bg_color = Color::Rgb(bg_r, bg_g, bg_b);
                    let fg_color = if is_selected {
                        Color::Rgb(10,10,10)
                    } else if is_match {
                        Color::Rgb(225,225,225)
                    } else {
                        let lum = 0.299*(bg_r as f64) + 0.587*(bg_g as f64) + 0.114*(bg_b as f64);
                        if lum < 140.0 { Color::Rgb(225,225,225) } else { Color::Rgb(10,10,10) }
                    };
                    let style = Style::default().bg(bg_color).fg(fg_color);
                    let label = format!(" {}", node.name);
                    let label_chars: Vec<char> = label.chars().collect();
                    let display_label = if w >= label_chars.len() {
                        let mut s = label;
                        s.push_str(&" ".repeat(w - s.len()));
                        s
                    } else {
                        if w == 1 {
                            ".".to_string()
                        } else {
                            label_chars.iter().take(w).collect()
                        }
                    };
                    if is_match {
                        if let Some(ref re) = search_pattern {
                            let mut last = 0;
                            let mut spans_match: Vec<Span> = Vec::new();
                            let mut matched_any = false;
                            for mat in re.find_iter(&display_label) {
                                matched_any = true;
                                let s = mat.start();
                                let e = mat.end();
                                if s > last {
                                    spans_match.push(Span::styled(display_label[last..s].to_string(), style));
                                }
                                let mtxt = &display_label[s..e];
                                let mstyle = Style::default().bg(bg_color).fg(Color::Rgb(225,10,10)).add_modifier(Modifier::BOLD);
                                spans_match.push(Span::styled(mtxt.to_string(), mstyle));
                                last = e;
                            }
                            if matched_any {
                                if last < display_label.len() {
                                    spans_match.push(Span::styled(display_label[last..].to_string(), style));
                                }
                                for s in spans_match { row_spans.push(s); }
                                current_x = end;
                                continue;
                            }
                        }
                    }
                    row_spans.push(Span::styled(display_label, style));
                    current_x = end;
                }
                if current_x < width {
                    row_spans.push(Span::raw(" ".repeat(width - current_x)));
                }
                lines.push(Line::from(row_spans));
            }

            let sel_node = &nodes[selected];
            let total_all = nodes[0].total as f64;
            let sel_total = sel_node.total;
            let percent_all = if total_all > 0.0 { sel_total as f64 / total_all * 100.0 } else { 0.0 };
            let sel_header = format!("Selected {}", "─".repeat(width.saturating_sub(9)));
            lines.push(Line::from(Span::styled(sel_header, Style::default().fg(Color::Yellow).add_modifier(Modifier::BOLD))));

            let sel_info = if zoom != 0 {
                let zoom_total = nodes[zoom].total as f64;
                if selected == zoom || nodes[selected].x0 >= nodes[zoom].x0 && nodes[selected].x1 <= nodes[zoom].x1 {
                    if zoom == selected {
                        format!("{} [{} samples, {:.2}% of all, 100.00% of zoomed]", sel_node.name, sel_total, percent_all)
                    } else {
                        let percent_zoomed = if zoom_total > 0.0 { sel_total as f64 / zoom_total * 100.0 } else { 0.0 };
                        format!("{} [{} samples, {:.2}% of all, {:.2}% of zoomed]", sel_node.name, sel_total, percent_all, percent_zoomed)
                    }
                } else {
                    format!("{} [{} samples, {:.2}% of all]", sel_node.name, sel_total, percent_all)
                }
            } else {
                format!("{} [{} samples, {:.2}% of all]", sel_node.name, sel_total, percent_all)
            };
            lines.push(Line::from(sel_info));

            if let Some(ref pat) = search_text {
                let match_header = format!("Match {}", "─".repeat(width.saturating_sub(6)));
                lines.push(Line::from(Span::styled(match_header, Style::default().fg(Color::Yellow).add_modifier(Modifier::BOLD))));
                let mut match_total: u64 = 0;
                for &idx in &search_matches {
                    match_total += nodes[idx].total;
                }
                let match_percent = if total_all > 0.0 { match_total as f64 / total_all * 100.0 } else { 0.0 };
                let match_info = if zoom != 0 {
                    let zoom_total = nodes[zoom].total as f64;
                    let percent_zoomed = if zoom_total >0.0 { match_total as f64 / zoom_total *100.0 } else {0.0};
                    format!("\"{}\" [{} samples, {:.2}% of all, {:.2}% of zoomed]", pat, match_total, match_percent, percent_zoomed)
                } else {
                    format!("\"{}\" [{} samples, {:.2}% of all]", pat, match_total, match_percent)
                };
                lines.push(Line::from(match_info));
            }

            if search_mode {
                let search_header = format!("Search {}", "─".repeat(width.saturating_sub(7)));
                lines.push(Line::from(Span::styled(search_header, Style::default().fg(Color::Yellow).add_modifier(Modifier::BOLD))));
                lines.push(Line::from(search_input.clone()));
            }

            if let Some(ref msg) = info_message {
                let info_header = format!("Info {}", "─".repeat(width.saturating_sub(5)));
                lines.push(Line::from(Span::styled(info_header, Style::default().fg(Color::Yellow).add_modifier(Modifier::BOLD))));
                lines.push(Line::from(msg.clone()));
            }

            if debug_flag {
                let debug_header = format!("Debug {}", "─".repeat(width.saturating_sub(6)));
                lines.push(Line::from(Span::styled(debug_header, Style::default().fg(Color::Yellow).add_modifier(Modifier::BOLD))));
                let elapsed = frame_start.elapsed();
                lines.push(Line::from(format!("Debug: flamegraph:{:.2?} render:{:.2?}", elapsed, Duration::from_millis(0))));
            }

            lines.push(Line::from(border.clone()));

            let hints = " [hjkl: move cursor] [f/b: scroll] [enter/esc: zoom] [/: search] [#: search like cursor] [n/N: next/prev match] [r: reset] [q: quit]";
            let hints_display = if hints.len() > width { &hints[..width] } else { hints };
            let mut hint_spans: Vec<Span> = Vec::new();
            let mut in_bracket = false;
            let mut current = String::new();
            for ch in hints_display.chars() {
                if ch == '[' {
                    if !current.is_empty() {
                        hint_spans.push(Span::raw(current.clone()));
                        current.clear();
                    }
                    in_bracket = true;
                    current.push(ch);
                } else if ch == ']' && in_bracket {
                    current.push(ch);
                    let inner = current[1..current.len()-1].to_string();
                    if let Some(colon) = inner.find(':') {
                        let key_part = &inner[..colon];
                        let rest = &inner[colon..];
                        hint_spans.push(Span::raw("["));
                        hint_spans.push(Span::styled(key_part.to_string(), Style::default().fg(Color::Yellow).add_modifier(Modifier::BOLD)));
                        hint_spans.push(Span::raw(format!("{}]", rest)));
                    } else {
                        hint_spans.push(Span::styled(current.clone(), Style::default().fg(Color::Yellow).add_modifier(Modifier::BOLD)));
                    }
                    current.clear();
                    in_bracket = false;
                } else {
                    current.push(ch);
                }
            }
            if !current.is_empty() {
                hint_spans.push(Span::raw(current));
            }
            lines.push(Line::from(hint_spans));

            let paragraph = Paragraph::new(lines);
            f.render_widget(paragraph, area);
        }).unwrap();

        if event::poll(Duration::from_millis(100)).unwrap() {
            if let Event::Key(key) = event::read().unwrap() {
                if key.kind != KeyEventKind::Press { continue; }
                match key.code {
                    KeyCode::Char('q') => { should_quit = true; }
                    KeyCode::Char('c') if key.modifiers.contains(event::KeyModifiers::CONTROL) => { should_quit = true; }
                    KeyCode::Char('j') | KeyCode::Down => {
                        if search_mode { continue; }
                        let children = &nodes[selected].children;
                        if !children.is_empty() {
                            let mut best = children[0];
                            let mut best_total = nodes[best].total;
                            for &c in children.iter().skip(1) {
                                let t = nodes[c].total;
                                if t > best_total || t == best_total {
                                    best = c;
                                    best_total = t;
                                }
                            }
                            selected = best;
                        }
                    }
                    KeyCode::Char('k') | KeyCode::Up => {
                        if search_mode { continue; }
                        if let Some(parent) = nodes[selected].parent { selected = parent; }
                    }
                    KeyCode::Char('h') | KeyCode::Left => {
                        if search_mode { continue; }
                        let zoom_node = &nodes[zoom];
                        let depth = nodes[selected].depth;
                        let mut visible: Vec<usize> = Vec::new();
                        for &idx in &depth_index[depth] {
                            let n = &nodes[idx];
                            if n.x1 <= zoom_node.x0 || n.x0 >= zoom_node.x1 { continue; }
                            visible.push(idx);
                        }
                        if let Some(pos) = visible.iter().position(|&i| i == selected) {
                            if pos > 0 { selected = visible[pos-1]; }
                        }
                    }
                    KeyCode::Char('l') | KeyCode::Right => {
                        if search_mode { continue; }
                        let zoom_node = &nodes[zoom];
                        let depth = nodes[selected].depth;
                        let mut visible: Vec<usize> = Vec::new();
                        for &idx in &depth_index[depth] {
                            let n = &nodes[idx];
                            if n.x1 <= zoom_node.x0 || n.x0 >= zoom_node.x1 { continue; }
                            visible.push(idx);
                        }
                        if let Some(pos) = visible.iter().position(|&i| i == selected) {
                            if pos + 1 < visible.len() { selected = visible[pos+1]; }
                        }
                    }
                    KeyCode::Char('f') => {
                        if search_mode { continue; }
                        let size = terminal.size().unwrap();
                        let height = size.height as usize;
                        let mut extra_bottom = 2;
                        if search_pattern.is_some() { extra_bottom +=2; }
                        if search_mode { extra_bottom +=2; }
                        if info_message.is_some() { extra_bottom+=2; }
                        if debug_flag { extra_bottom+=2; }
                        extra_bottom+=2;
                        let flame_h = height.saturating_sub(3+extra_bottom);
                        scroll_offset = scroll_offset.saturating_add(flame_h);
                        let max_scroll = max_depth.saturating_sub(flame_h.saturating_sub(1));
                        if scroll_offset > max_scroll { scroll_offset = max_scroll; }
                        if scroll_offset < depth_index.len() {
                            let mut visible_at_offset: Vec<usize> = Vec::new();
                            let zoom_node = &nodes[zoom];
                            for &idx in &depth_index[scroll_offset] {
                                let n = &nodes[idx];
                                if n.x1 <= zoom_node.x0 || n.x0 >= zoom_node.x1 { continue; }
                                visible_at_offset.push(idx);
                            }
                            if !visible_at_offset.is_empty() { selected = visible_at_offset[0]; }
                        }
                    }
                    KeyCode::Char('b') => {
                        if search_mode { continue; }
                        let size = terminal.size().unwrap();
                        let height = size.height as usize;
                        let mut extra_bottom = 2;
                        if search_pattern.is_some() { extra_bottom +=2; }
                        if search_mode { extra_bottom +=2; }
                        if info_message.is_some() { extra_bottom+=2; }
                        if debug_flag { extra_bottom+=2; }
                        extra_bottom+=2;
                        let flame_h = height.saturating_sub(3+extra_bottom);
                        scroll_offset = scroll_offset.saturating_sub(flame_h);
                        if scroll_offset < depth_index.len() {
                            let mut visible_at_offset: Vec<usize> = Vec::new();
                            let zoom_node = &nodes[zoom];
                            for &idx in &depth_index[scroll_offset] {
                                let n = &nodes[idx];
                                if n.x1 <= zoom_node.x0 || n.x0 >= zoom_node.x1 { continue; }
                                visible_at_offset.push(idx);
                            }
                            if !visible_at_offset.is_empty() { selected = visible_at_offset[0]; }
                        }
                    }
                    KeyCode::Char('g') => {
                        if search_mode { continue; }
                        scroll_offset = 0;
                        selected = 0;
                    }
                    KeyCode::Char('G') => {
                        if search_mode { continue; }
                        let size = terminal.size().unwrap();
                        let height = size.height as usize;
                        let mut extra_bottom = 2;
                        if search_pattern.is_some() { extra_bottom +=2; }
                        if search_mode { extra_bottom +=2; }
                        if info_message.is_some() { extra_bottom+=2; }
                        if debug_flag { extra_bottom+=2; }
                        extra_bottom+=2;
                        let flame_h = height.saturating_sub(3+extra_bottom);
                        let max_scroll = max_depth.saturating_sub(flame_h.saturating_sub(1));
                        scroll_offset = max_scroll;
                        if scroll_offset < depth_index.len() {
                            let mut visible_at_offset: Vec<usize> = Vec::new();
                            let zoom_node = &nodes[zoom];
                            for &idx in &depth_index[scroll_offset] {
                                let n = &nodes[idx];
                                if n.x1 <= zoom_node.x0 || n.x0 >= zoom_node.x1 { continue; }
                                visible_at_offset.push(idx);
                            }
                            if !visible_at_offset.is_empty() { selected = visible_at_offset[0]; }
                        }
                    }
                    KeyCode::Enter => {
                        if search_mode {
                            let pattern = search_input.clone();
                            if pattern.is_empty() {
                                search_pattern = None;
                                search_text = None;
                                search_matches.clear();
                                info_message = None;
                            } else {
                                match regex::Regex::new(&pattern) {
                                    Ok(re) => {
                                        search_pattern = Some(re);
                                        search_text = Some(pattern.clone());
                                        search_matches.clear();
                                        if let Some(ref re) = search_pattern {
                                            for (i, node) in nodes.iter().enumerate() {
                                                if re.is_match(&node.name) { search_matches.push(i); }
                                            }
                                        }
                                        search_current = 0;
                                        info_message = None;
                                    }
                                    Err(_) => {
                                        info_message = Some(format!("Invalid regex: {}", pattern));
                                        search_pattern = None;
                                        search_text = None;
                                        search_matches.clear();
                                    }
                                }
                            }
                            search_mode = false;
                            search_input.clear();
                        } else {
                            zoom = selected;
                        }
                    }
                    KeyCode::Esc => {
                        if search_mode {
                            search_mode = false;
                            search_input.clear();
                        } else {
                            zoom = 0;
                            info_message = None;
                        }
                    }
                    KeyCode::Char('/') => {
                        if !search_mode {
                            search_mode = true;
                            search_input.clear();
                        } else {
                            search_input.push('/');
                        }
                    }
                    KeyCode::Char('#') => {
                        if search_mode {
                            search_input.push('#');
                        } else {
                            let name = nodes[selected].name.clone();
                            let pattern = format!("^{}$", regex::escape(&name));
                            match regex::Regex::new(&pattern) {
                                Ok(re) => {
                                    search_pattern = Some(re);
                                    search_text = Some(pattern);
                                    search_matches.clear();
                                    if let Some(ref re) = search_pattern {
                                        for (i, node) in nodes.iter().enumerate() {
                                            if re.is_match(&node.name) { search_matches.push(i); }
                                        }
                                    }
                                    search_current = 0;
                                    if !search_matches.is_empty() && !search_matches.contains(&selected) {
                                        selected = search_matches[0];
                                    }
                                    info_message = None;
                                }
                                Err(_) => {
                                    info_message = Some(format!("Invalid regex: {}", name));
                                }
                            }
                        }
                    }
                    KeyCode::Char('n') => {
                        if search_mode {
                            search_input.push('n');
                        } else if !search_matches.is_empty() {
                            search_current = (search_current + 1) % search_matches.len();
                            selected = search_matches[search_current];
                        }
                    }
                    KeyCode::Char('N') => {
                        if search_mode {
                            search_input.push('N');
                        } else if !search_matches.is_empty() {
                            if search_current == 0 {
                                search_current = search_matches.len() - 1;
                            } else {
                                search_current -= 1;
                            }
                            selected = search_matches[search_current];
                        }
                    }
                    KeyCode::Char('r') => {
                        if search_mode {
                            search_input.push('r');
                        } else {
                            selected = 0;
                            zoom = 0;
                            scroll_offset = 0;
                            search_pattern = None;
                            search_text = None;
                            search_matches.clear();
                            search_current = 0;
                            search_mode = false;
                            search_input.clear();
                            info_message = None;
                        }
                    }
                    KeyCode::Backspace => {
                        if search_mode { search_input.pop(); }
                    }
                    KeyCode::Char(c) => {
                        if search_mode { search_input.push(c); }
                    }
                    _ => {}
                }

                let size = terminal.size().unwrap();
                let height = size.height as usize;
                let mut extra_bottom = 2;
                if search_pattern.is_some() { extra_bottom +=2; }
                if search_mode { extra_bottom +=2; }
                if info_message.is_some() { extra_bottom+=2; }
                if debug_flag { extra_bottom+=2; }
                extra_bottom+=2;
                let flame_h = height.saturating_sub(3+extra_bottom);
                let sel_depth = nodes[selected].depth;
                if sel_depth < scroll_offset {
                    scroll_offset = sel_depth;
                } else if flame_h >0 && sel_depth >= scroll_offset + flame_h {
                    scroll_offset = sel_depth - flame_h + 1;
                }
            }
        }

        if should_quit { break; }
    }

    disable_raw_mode()?;
    terminal.backend_mut().execute(LeaveAlternateScreen)?;
    terminal.show_cursor()?;
    Ok(())
}
